import django.db.models.functions.text
import django.utils.timezone
from django.db import migrations, models


def merge_and_date(apps, schema_editor):
    """El correo en minúsculas, con una sola fila por persona (la de actividad más reciente),
    y la fecha del último cambio de estado según lo que se sabe de cada fila."""
    Subscriber = apps.get_model("community", "NewsletterSubscriber")

    def activity(sub):
        return max(d for d in (sub.confirmed_at, sub.confirm_token_at, sub.created_at) if d)

    by_email = {}
    for sub in Subscriber.objects.all():
        by_email.setdefault(sub.email.strip().lower(), []).append(sub)
    for email, subs in by_email.items():
        keep = max(subs, key=activity)
        for other in subs:
            if other.pk != keep.pk:
                other.delete()
        keep.email = email
        if keep.status == "confirmed":
            keep.status_changed_at = keep.confirmed_at or keep.created_at
        elif keep.status == "pending":
            keep.status_changed_at = keep.confirm_token_at or keep.created_at
        else:
            # La baja no dejaba fecha: la del alta, desde la que medía la purga hasta ahora.
            keep.status_changed_at = keep.created_at
        keep.save(update_fields=["email", "status_changed_at"])


